import fs from 'node:fs';
import dotenv from 'dotenv';
process.env.DATABASE_URL=dotenv.parse(fs.readFileSync('apps/operator/.env.local')).DATABASE_URL;
const {getOrgPg}=await import('@papercusp/db-org');
const {holdCensus,renderHoldCensus}=await import('./packages/operator-core/lib/hold-census.ts');
const {classifyHolds}=await import('./packages/operator-core/lib/hold-registry.ts');
const {sql}=getOrgPg();
const started=Date.now();
const result=await sql.begin('isolation level repeatable read read only',async client=>{
 const [db]=await client`SELECT current_database() AS database,inet_server_port() AS port`;
 const known=await client`SELECT feature_id FROM harness_shared.work_items WHERE workspace_id='papercusp-workspace' AND harness_slug='papercusp' AND feature_id='WI-10006215'`;
 if(db.database!=='papercusp'||db.port!==5432||known.length!==1)throw new Error('canonical database/positive control mismatch');
 const managed=await client`SELECT system_identifier::text FROM pg_control_system()`;
 const census=await holdCensus('papercusp-workspace',{harness:'papercusp',sampleLimit:50,sql:client});
 const unknownControl=classifyHolds({status:'open',payload:{implementationReadiness:{status:'blocked',reason:'__unknown_P001_positive_control__'}}});
 const knownControl=classifyHolds({status:'open',payload:{_claimHold:true}});
 if(unknownControl.length!==1||unknownControl[0].entry!==null||knownControl.length!==1||knownControl[0].entry===null)throw new Error('classifier controls failed');
 return {at:new Date().toISOString(),elapsedMs:Date.now()-started,database:db,systemIdentifier:managed[0]?.system_identifier,positiveControl:known[0].feature_id,consistentSnapshot:'repeatable-read/read-only',classifierControls:{unregisteredDetected:true,registeredParkMapped:true},note:renderHoldCensus(census),census};
});
console.log(JSON.stringify(result));
await sql.end({timeout:2});

